{
  "name": "electron-archivebox",
  "version": "1.13.0",
  "description": "Desktop Electron app for the ArchiveBox internet archiver",
  "main": "main.js",
  "scripts": {
    "start": "electron-forge start",
    "lint": "eslint .",
    "capture-screenshots": "node scripts/capture-screenshots.js",
    "package": "electron-forge package",
    "make": "electron-forge make",
    "build-site": "node scripts/build-site.js"
  },
  "engines": {
    "node": ">=22.14.0",
    "npm": ">=10.9.0"
  },
  "repository": "https://github.com/ArchiveBox/electron-archivebox",
  "keywords": [
    "ArchiveBox",
    "internet",
    "archiving",
    "GUI",
    "desktop",
    "web"
  ],
  "author": "Nick Sweeting",
  "license": "MIT",
  "devDependencies": {
    "@electron-forge/cli": "^8.0.1",
    "@electron-forge/maker-deb": "^8.0.1",
    "@electron-forge/maker-dmg": "^8.0.1",
    "@electron-forge/maker-rpm": "^8.0.1",
    "@electron-forge/maker-squirrel": "^8.0.1",
    "electron": "^44.5.1",
    "eslint": "^10.12.0",
    "playwright": "^1.63.0"
  },
  "dependencies": {
    "dockerode": "^5.0.1",
    "electron-squirrel-startup": "^1.0.1"
  },
  "config": {
    "forge": {
      "packagerConfig": {
        "asar": true,
        "ignore": [
          "^/artifacts($|/)",
          "^/docs($|/)",
          "^/_site($|/)",
          "^/screenshots($|/)",
          "^/scripts($|/)",
          "^/\\.github($|/)",
          "^/node_modules/cpu-features($|/)",
          "^/node_modules/ssh2/lib/protocol/crypto/build($|/)",
          "^/out($|/)"
        ],
        "icon": "assets/icon"
      },
      "makers": [
        {
          "name": "@electron-forge/maker-squirrel",
          "config": {
            "name": "archivebox"
          }
        },
        {
          "name": "@electron-forge/maker-dmg",
          "platforms": [
            "darwin"
          ],
          "config": {
            "name": "ArchiveBox-Mac",
            "icon": "assets/icon.icns"
          }
        },
        {
          "name": "@electron-forge/maker-deb",
          "config": {
            "options": {
              "icon": "assets/icon.png"
            }
          }
        },
        {
          "name": "@electron-forge/maker-rpm",
          "config": {
            "options": {
              "icon": "assets/icon.png"
            }
          }
        }
      ]
    }
  },
  "releaseRunBase": 50
}

/* Optional landing-page languages. Remove this file, its script tag, and the
   es/fr/zh/ru/ar folders to retire the feature. No shared-site dependency. */
(() => {
  const script = document.currentScript;
  if (!script) return;
  const base = new URL('.', script.src);
  const languages = [
    ['en', '🇬🇧', 'English', 'Choose language'],
    ['es', '🇪🇸', 'Español', 'Elegir idioma'],
    ['fr', '🇫🇷', 'Français', 'Choisir la langue'],
    ['zh', '🇨🇳', '中文', '选择语言'],
    ['ru', '🇷🇺', 'Русский', 'Выбрать язык'],
    ['ar', '🇸🇦', 'العربية', 'اختر اللغة'],
  ];
  const codes = languages.map(([code]) => code);
  const relative = location.pathname.startsWith(base.pathname)
    ? location.pathname.slice(base.pathname.length) : null;
  const current = codes.includes(relative?.split('/')[0]) ? relative.split('/')[0] : 'en';
  const key = `archivebox-language:${base.pathname}`;
  const target = code => {
    const url = new URL(code === 'en' ? './' : `${code}/`, base);
    url.search = location.search;
    url.searchParams.delete('lang');
    url.hash = location.hash;
    return url;
  };
  // Explicit language URLs always win; only the original entry page detects.
  if (relative === '' || relative === 'index.html') {
    let saved;
    try { saved = localStorage.getItem(key); } catch { /* Storage is optional. */ }
    const detected = (navigator.languages || [navigator.language])
      .map(language => language.toLowerCase().split('-')[0])
      .find(language => codes.includes(language));
    const requested = new URL(location.href).searchParams.get('lang');
    const preferred = codes.includes(requested) ? requested : codes.includes(saved) ? saved : detected || 'en';
    if (preferred !== 'en') {
      location.replace(target(preferred));
      return;
    }
  }
  const active = languages.find(([code]) => code === current);
  const style = document.createElement('style');
  style.textContent = `
    .abx-language{position:relative;flex:0 0 auto;direction:ltr;font:13px/1.4 system-ui,sans-serif;color:#4d424b;letter-spacing:normal}
    .abx-language>summary{display:flex;align-items:center;justify-content:center;gap:5px;min-width:52px;min-height:36px;padding:4px;cursor:pointer;list-style:none;border-radius:6px;white-space:nowrap}
    .abx-language>summary::-webkit-details-marker{display:none}
    .abx-language>summary:hover{background:#f4e8ed}
    .abx-language>summary:focus-visible,.abx-language a:focus-visible{outline:2px solid #9b2854;outline-offset:2px}
    .abx-language .abx-language-flag{font-size:18px;line-height:1}
    .abx-language .abx-language-options{position:absolute;right:0;top:100%;z-index:1100;min-width:160px;padding:6px;background:#fcfaf7;color:#28252a;border:1px solid #ded4d8;border-radius:8px;box-shadow:0 6px 24px #28252a20;text-align:left}
    .abx-language .abx-language-options a{display:flex;gap:9px;align-items:center;margin:0;padding:8px 10px;border-radius:4px;color:#4d424b;text-decoration:none;font:14px/1.4 system-ui,sans-serif;white-space:nowrap}
    .abx-language .abx-language-options a:hover,.abx-language a[aria-current=page]{background:#f4e8ed}
    .abx-language-fallback{position:fixed;right:12px;top:10px;z-index:1000;background:#fcfaf7;border:1px solid #ded4d8;border-radius:8px}
    html[dir=rtl] .abx-header{direction:ltr}
    html[dir=rtl] main{direction:rtl;text-align:right}
    html[dir=rtl] pre,html[dir=rtl] code{direction:ltr;unicode-bidi:isolate}
  `;
  document.head.append(style);
  const menu = document.createElement('details');
  menu.className = 'abx-language';
  const summary = document.createElement('summary');
  summary.setAttribute('aria-label', `${active[3]}: ${active[2]}`);
  summary.title = active[3];
  const flag = document.createElement('span');
  flag.className = 'abx-language-flag';
  flag.setAttribute('aria-hidden', 'true');
  flag.textContent = active[1];
  const codeLabel = document.createElement('span');
  codeLabel.textContent = current.toUpperCase();
  summary.append(flag, codeLabel);
  const options = document.createElement('div');
  options.className = 'abx-language-options';
  for (const [code, emoji, name] of languages) {
    const link = document.createElement('a');
    link.href = target(code).href;
    link.lang = code;
    link.hreflang = code;
    if (code === current) link.setAttribute('aria-current', 'page');
    link.textContent = `${emoji} ${name}`;
    link.addEventListener('click', () => {
      try { localStorage.setItem(key, code); } catch {
        const url = target(code);
        url.searchParams.set('lang', code);
        link.href = url.href;
      }
    });
    options.append(link);
  }
  menu.append(summary, options);
  const fitMenu = () => {
    if (!menu.open) return;
    options.style.transform = '';
    const bounds = options.getBoundingClientRect();
    const shift = Math.max(8 - bounds.left, Math.min(0, innerWidth - 8 - bounds.right));
    options.style.transform = `translateX(${shift}px)`;
  };
  summary.addEventListener('click', event => {
    event.preventDefault();
    menu.open = !menu.open;
    fitMenu();
  });
  menu.addEventListener('toggle', fitMenu);
  window.addEventListener('resize', fitMenu);
  const nav = document.querySelector('.abx-header .abx-nav');
  if (nav) nav.append(menu);
  else { menu.classList.add('abx-language-fallback'); document.body.append(menu); }
  document.addEventListener('click', event => { if (!menu.contains(event.target)) menu.open = false; });
  menu.addEventListener('keydown', event => {
    if (event.key === 'Escape') { menu.open = false; summary.focus(); }
  });
})();

// Highlight platform choices without changing links, tabs, or navigation.
(() => {
  const ua = window.navigator.userAgent;
  const platform = /Android/i.test(ua) ? 'android'
    : /iPhone|iPad|iPod/i.test(ua) || (/Macintosh/i.test(ua) && window.navigator.maxTouchPoints > 1) ? 'ios'
    : /Windows/i.test(ua) ? 'windows'
    : /Macintosh|Mac OS X/i.test(ua) ? 'macos'
    : /Linux/i.test(ua) ? 'linux' : '';
  document.querySelectorAll('[data-platform-group]').forEach(group => {
    const choices = Array.from(group.querySelectorAll('[data-platform]'));
    const matches = choices.filter(choice => platform && choice.dataset.platform.split(' ').includes(platform));
    const highlighted = matches.length ? matches : choices.filter(choice => choice.hasAttribute('data-platform-default'));
    choices.forEach(choice => choice.classList.toggle('is-platform-match', highlighted.includes(choice)));
  });
})();

const assert = require('node:assert/strict')
const { execFileSync } = require('node:child_process')
const { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync } = require('node:fs')
const { tmpdir } = require('node:os')
const path = require('node:path')

// Exercise the actual release script against real tags and a clean checkout.
const directory = mkdtempSync(path.join(tmpdir(), 'electron-release-version-'))
const git = (...args) => execFileSync('git', args, { cwd: directory, stdio: 'pipe' })
const source = process.argv[2] || path.join(__dirname, 'release-version.js')
try {
    mkdirSync(path.join(directory, 'scripts'))
    writeFileSync(path.join(directory, 'scripts/release-version.js'), readFileSync(source))
    writeFileSync(path.join(directory, 'package.json'), JSON.stringify({ version: '0.1.0', releaseRunBase: 50 }))
    writeFileSync(path.join(directory, 'package-lock.json'), JSON.stringify({ version: '0.1.0', packages: { '': { version: '0.1.0' } } }))
    git('init', '-b', 'main')
    git('config', 'user.name', 'ArchiveBox version test')
    git('config', 'user.email', 'version-test@example.invalid')
    git('add', '.')
    git('commit', '-m', 'Release source')
    git('tag', 'v0.1.7')
    const run = event => execFileSync(process.execPath, ['scripts/release-version.js'], {
        cwd: directory, encoding: 'utf8',
        env: { ...process.env, GITHUB_EVENT_NAME: event, GITHUB_REF: 'refs/heads/main', GITHUB_RUN_NUMBER: '70', GITHUB_ENV: '' },
    })
    run('schedule')
    assert.equal(JSON.parse(readFileSync(path.join(directory, 'package.json'))).version, '0.1.7', 'Scheduled capture must use the published version, not reserve a new release')
    const provenance = JSON.parse(execFileSync(process.execPath, ['-e', "console.log(JSON.stringify(require('./scripts/release-version').sourceProvenance()))"], {
        cwd: directory, encoding: 'utf8',
        env: { ...process.env, GITHUB_EVENT_NAME: 'schedule', GITHUB_REF: 'refs/heads/main', GITHUB_RUN_NUMBER: '70' },
    }))
    assert.equal(provenance.dirty, false)
    assert.equal(provenance.versionStamp.version, '0.1.7')
    git('restore', 'package.json', 'package-lock.json')
    run('push')
    assert.equal(JSON.parse(readFileSync(path.join(directory, 'package.json'))).version, '0.1.20', 'Normal push release numbering must stay unchanged')
    console.log('Scheduled capture identity and push release numbering verified with real git history.')
} finally {
    rmSync(directory, { recursive: true, force: true })
}

:root{color-scheme:light;--ink:#28252a;--muted:#716c74;--accent:#9b2854;--paper:#fcfaf7;--line:#e9e2e3}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:var(--paper);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}a{color:var(--accent);text-underline-offset:.2em}a:hover{color:#6d1738}a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.skip-link{position:fixed;top:-80px;left:16px;background:white;padding:12px;z-index:30}.skip-link:focus{top:12px}main{max-width:1200px;margin:auto;padding:0 28px 80px;font-size:17px;line-height:1.75;overflow-wrap:anywhere}h1,h2,h3{letter-spacing:-.045em;line-height:1.15}h1{font-size:clamp(40px,6vw,76px);font-weight:760;margin:20px 0 28px}h2{font-size:clamp(28px,3.5vw,38px);margin:0 0 24px}section{margin:64px 0}.hero{position:relative;padding:15px 0 0}.hero:before{content:"";position:absolute;z-index:-1;inset:-50px -20px -150px;background:radial-gradient(ellipse at 30% 30%,#f3dce780,transparent 65%);pointer-events:none}.eyebrow{color:var(--accent);font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.lead{max-width:750px;font-size:23px;line-height:1.6;color:var(--muted)}.actions{display:flex;align-items:center;gap:24px;flex-wrap:wrap;margin:30px 0}.button{display:inline-block;background:var(--accent);color:white;padding:12px 23px;border-radius:8px;text-decoration:none;font-weight:650}.button:hover{background:#6d1738;color:white}.apple-note,.note{color:var(--muted);font-size:15px}.features{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:35px}.features h2{font-size:25px}.features p{color:var(--muted)}li+li{margin-top:14px}li::marker{color:var(--accent);font-weight:650}.provenance,.capture-meta{font-size:13px;color:var(--muted)}.capture{margin:48px 0 64px}.capture h2{font-size:29px;margin-bottom:10px}figure{margin:0;padding:14px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(140deg,#fff,#f8edf2)}img{max-width:100%;height:auto}figure img{display:block;width:100%;height:auto;border-radius:6px}figcaption{font-size:12px;color:var(--muted);padding-top:12px;text-align:center}.capture-index{display:flex;gap:10px 22px;flex-wrap:wrap;padding:0;list-style:none;font-size:14px}.capture-index li{margin:0}code{font-size:.86em;background:#f5f0f3;padding:.15em .3em;border-radius:4px}.empty{padding:25px;border:1px solid var(--line);border-radius:12px}@media(max-width:650px){main{padding:0 20px 45px;font-size:16px}section{margin:42px 0}.features{grid-template-columns:1fr;gap:18px}.features h2{margin-bottom:12px}.lead{font-size:20px}figure{padding:7px;border-radius:10px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

.desktop-downloads { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin: 18px 0; }
.desktop-downloads .desktop-download { display: flex; align-items: center; gap: 12px; padding: 15px 16px; border: 1px solid #9b285455; border-radius: 10px; background: #9b28541a; color: inherit; text-decoration: none; transition: background .15s, border-color .15s; }
.desktop-downloads .desktop-download:hover { background: #9b285433; border-color: #c45b83; }
.desktop-download > svg, .desktop-download .platform-symbol { flex: 0 0 25px; width: 25px; height: 28px; font-size: 25px; line-height: 28px; text-align: center; }
.desktop-download strong { display: block; font-size: 15px; line-height: 1.4; }
.desktop-download small { display: block; margin-top: 3px; font-size: 11px; line-height: 1.5; opacity: .75; }
.desktop-download .download-arrow { margin-left: auto; font-size: 21px; }
.desktop-download:focus-visible { outline: 3px solid #c45b83; outline-offset: 4px; }
@media (max-width: 480px) { .desktop-downloads { grid-template-columns: 1fr; } }

.download-cta { display: inline-flex; align-items: center; gap: 10px; white-space: nowrap; }
.download-cta-platforms { display: inline-flex; align-items: center; gap: 6px; line-height: 1; }
.download-cta svg { width: 18px; height: 18px; flex: none; }
.download-cta-penguin { width: 22px; height: 22px; flex: none; }
.download-cta > svg { margin-left: 6px; }

.button.apple-cta { background: #171717; color: #fff; }
.button.apple-cta:hover { background: #383838; color: #fff; }

.actions .button[data-platform] { background: #171717; color: #fff; }
.actions .button[data-platform]:hover { background: #383838; }
.actions .button.is-platform-match,
.desktop-downloads .desktop-download.is-platform-match { background: var(--accent); color: #fff; border-color: var(--accent); }
.actions .button.is-platform-match:hover,
.desktop-downloads .desktop-download.is-platform-match:hover { background: #782040; }

.desktop-download-card { border: 1px solid #9b285455; border-radius: 10px; background: #9b28541a; }
.desktop-download-card .desktop-download { border: 0; background: transparent; }
.desktop-download-note { margin: 0; padding: 0 16px 15px; font-size: 12px; line-height: 1.5; color: var(--muted); }

const nodeGlobals = {
    AbortController: 'readonly',
    Buffer: 'readonly',
    URL: 'readonly',
    __dirname: 'readonly',
    clearTimeout: 'readonly',
    console: 'readonly',
    fetch: 'readonly',
    module: 'readonly',
    process: 'readonly',
    require: 'readonly',
    setTimeout: 'readonly',
}

const browserGlobals = {
    URLSearchParams: 'readonly',
    location: 'readonly',
    localStorage: 'readonly',
    navigator: 'readonly',
    innerWidth: 'readonly',
    document: 'readonly',
    window: 'readonly',
}

module.exports = [
    {
        files: ['**/*.js'],
        ignores: ['node_modules/**', 'out/**', 'artifacts/**'],
        languageOptions: {
            ecmaVersion: 'latest',
            sourceType: 'commonjs',
            globals: {
                ...nodeGlobals,
                ...browserGlobals,
            },
        },
        rules: {
            'no-constant-condition': ['error', { checkLoops: false }],
            'no-undef': 'error',
            'no-unreachable': 'error',
        },
    },
]

let state = null
let route = new URLSearchParams(window.location.search).get('route') || '/public/'
let settingsOpen = route === 'settings'
let networkSaving = false
let renderedNetwork = ''
const element = id => document.getElementById(id)
const busyPhases = ['connecting', 'pulling', 'starting', 'stopping']
const normalizeRoute = value => value?.startsWith('/') && !value.startsWith('//') ? value : '/public/'
const setArchiveRoute = value => {
    if (value === 'settings') { settingsOpen = true; renderState(state); return }
    settingsOpen = false
    route = normalizeRoute(value)
    if (state?.phase === 'running') {
        window.archivebox.navigate(route)
    }
    renderState(state)
}
const renderState = next => {
    if (!next) return
    const wasRunning = state?.phase === 'running'
    state = next
    const running = state.phase === 'running'
    const busy = busyPhases.includes(state.phase)
    element('service-status').textContent = running ? state.message : `ArchiveBox • ${state.phase}`
    element('service-panel').dataset.state = state.phase
    element('service-panel').hidden = running || settingsOpen
    element('settings-panel').hidden = !settingsOpen
    window.archivebox.setArchiveVisible(running && !settingsOpen)
    element('service-message').textContent = state.message
    element('service-heading').textContent = ({ setup: 'Welcome to ArchiveBox', error: 'ArchiveBox needs your attention', stopped: 'ArchiveBox is stopped', connecting: 'Connecting to Docker', pulling: 'Downloading ArchiveBox', starting: 'Starting ArchiveBox', stopping: 'Stopping ArchiveBox' })[state.phase] || 'ArchiveBox'
    element('setup-form').hidden = !state.setupNeeded || busy
    element('start-service').hidden = !['error', 'stopped'].includes(state.phase) || state.setupNeeded
    element('start-service').textContent = state.phase === 'error' ? 'Try again' : 'Start ArchiveBox'
    document.querySelectorAll('[data-route]').forEach(button => {
        button.disabled = !running
        button.classList.toggle('is-active', running && !settingsOpen && button.dataset.route === route)
    })
    element('settings-button').classList.toggle('is-active', settingsOpen)
    element('settings-button').setAttribute('aria-pressed', String(settingsOpen))
    document.querySelectorAll('[data-action]').forEach(button => {
        button.disabled = busy && !['docker-help', 'open-data'].includes(button.dataset.action)
    })
    element('stop-service').disabled = busy || !running
    element('restart-service').disabled = busy || state.setupNeeded
    element('update-service').disabled = busy || state.setupNeeded
    element('settings-status').textContent = state.message
    element('settings-data').textContent = state.dataDir
    element('settings-origin').textContent = state.origin
    element('settings-image').textContent = state.image
    const networkKey = JSON.stringify(state.network)
    if (state.network && networkKey !== renderedNetwork) {
        element('network-scope').value = state.network.scope
        element('network-bind-address').value = state.network.bindAddress
        element('network-port').value = state.network.port
        element('network-base-url').value = state.network.baseURL
        element('network-bind-label').hidden = state.network.scope !== 'custom'
        renderedNetwork = networkKey
    }
    element('network-save').textContent = state.setupNeeded ? 'Save network settings' : 'Apply & restart'
    element('network-form').querySelectorAll('input, select, button').forEach(control => { control.disabled = busy || networkSaving })
    if (running && !wasRunning) {
        if (settingsOpen) window.archivebox.navigate(normalizeRoute(route))
        else setArchiveRoute(route)
    }
}
const action = async (name, credentials) => {
    element('settings-error').textContent = ''
    try {
        renderState(await window.archivebox.action(name, credentials))
        if (name === 'copy-address') element('copy-address').textContent = 'Address copied'
    }
    catch (error) {
        element('settings-error').textContent = error.message
        element('service-message').textContent = error.message
    }
}
window.addEventListener('DOMContentLoaded', async () => {
    for (const name of ['minimize', 'maximize', 'close']) {
        element(`${name}-window`).addEventListener('click', () => window.archivebox.window[name]())
    }
    document.querySelectorAll('.menu-item').forEach(button => button.addEventListener('click', () => window.archivebox.openMenu(button.textContent)))
    document.querySelectorAll('[data-route]').forEach(button => button.addEventListener('click', () => setArchiveRoute(button.dataset.route)))
    document.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', () => void action(button.dataset.action)))
    element('settings-button').addEventListener('click', () => { settingsOpen = !settingsOpen; renderState(state) })
    element('close-settings').addEventListener('click', () => { settingsOpen = false; renderState(state) })
    element('setup-network-settings').addEventListener('click', () => { settingsOpen = true; renderState(state) })
    element('network-scope').addEventListener('change', () => { element('network-bind-label').hidden = element('network-scope').value !== 'custom' })
    element('network-form').addEventListener('submit', async event => {
        event.preventDefault()
        const settings = { scope: element('network-scope').value, bindAddress: element('network-bind-address').value, port: Number(element('network-port').value), baseURL: element('network-base-url').value }
        networkSaving = true
        element('network-status').textContent = state.setupNeeded ? 'Saving network settings…' : 'Applying network settings and restarting…'
        renderState(state)
        try {
            const next = await window.archivebox.action('save-network', settings)
            renderState(next)
            element('network-status').textContent = `Network settings saved. Listen address: ${next.network.bindAddress}:${next.network.port}.`
        } catch (error) { element('network-status').textContent = error.message }
        finally { networkSaving = false; renderState(state) }
    })
    element('setup-form').addEventListener('submit', event => {
        event.preventDefault()
        void action('start', { username: element('setup-username').value, email: element('setup-email').value, password: element('setup-password').value })
        element('setup-password').value = ''
    })
    const content = document.querySelector('.archive-content')
    new window.ResizeObserver(() => window.archivebox.setArchiveTop(content.getBoundingClientRect().top)).observe(content)
