const { execFileSync } = require('node:child_process')

const root = path.resolve(__dirname, '..')
const repo = 'https://github.com/ArchiveBox/electron-archivebox'
const canonical = 'https://electron.archivebox.io/'
const option = (name, fallback) => {
    const index = process.argv.indexOf(name)
    return index < 0 ? fallback : process.argv[index + 1]
}
const base = `/${option('--baseurl', '').replace(/^\/+|\/+$/g, '')}/`.replace('//', '/')
const input = path.resolve(root, option('--screenshots-dir', 'artifacts/screenshots'))
const output = path.resolve(root, option('--output', '_site'))
const escape = value => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]))

async function main() {
    const revision = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim()
    const captureRunPath = option('--capture-run', null)
    const captureRun = captureRunPath ? JSON.parse(await fs.readFile(path.resolve(root, captureRunPath), 'utf8')) : null
    if (captureRun && (!/^[a-f0-9]{40}$/.test(captureRun.commit) || !/^[1-9]\d*$/.test(captureRun.runId) || !/^\d+\.\d+\.\d+$/.test(captureRun.appVersion))) throw new Error('Invalid restored capture run metadata')
    const expectedCommit = captureRun?.commit || process.env.GITHUB_SHA
    const expectedRunId = captureRun?.runId || process.env.GITHUB_RUN_ID
    const expectedVersion = captureRun?.appVersion || (expectedCommit && require('./release-version').releaseVersion())
    const manifests = []
    for (const platform of ['linux', 'windows', 'macos']) {
        let captureManifest
        try {
            captureManifest = JSON.parse(await fs.readFile(path.join(input, platform, 'manifest.json'), 'utf8'))
        } catch (error) {
            if (error.code !== 'ENOENT' || !process.argv.includes('--allow-missing-screenshots')) throw error
            continue
        }
        if (captureManifest.schemaVersion !== 1 || !/^[a-f0-9]{40}$/.test(captureManifest.commit) || !captureManifest.appVersion || !Number.isFinite(Date.parse(captureManifest.generatedAt)) || !captureManifest.screenshots?.length || !captureManifest.requiredScreenshots?.length) throw new Error('Incomplete capture provenance or coverage contract')
        if (expectedCommit) {
            const expectedScope = platform === 'linux' ? 'full' : 'startup-only'
            const expectedPlatform = { linux: /^linux-/, windows: /^win32-/, macos: /^darwin-/ }[platform]
            if (captureManifest.commit !== expectedCommit || captureManifest.dirty !== false || captureManifest.packaged !== true || captureManifest.captureScope !== expectedScope || !expectedPlatform.test(captureManifest.platform)) throw new Error(`Capture provenance does not match this CI build: ${platform}`)
            if (captureManifest.appVersion !== expectedVersion) throw new Error(`Capture app version does not match this release: ${platform}`)
        }
        if (captureManifest.captureScope === 'full' && (!captureManifest.dockerImage?.reference || !/^sha256:[a-f0-9]{64}$/.test(captureManifest.dockerImage?.id))) throw new Error(`Missing Docker image provenance: ${platform}`)
        if (expectedRunId && (String(captureManifest.workflowRun?.id) !== expectedRunId || captureManifest.workflowRun?.url !== `${repo}/actions/runs/${expectedRunId}`)) throw new Error(`Capture belongs to a different CI run: ${platform}`)
        const ids = new Set()
        for (const capture of captureManifest.screenshots) {
            if (!/^[a-z][a-z0-9-]*$/.test(capture.id) || ids.has(capture.id) || !capture.title || capture.file !== `${capture.id}.png`) throw new Error('Invalid screenshot entry')
            ids.add(capture.id)
            const image = await fs.readFile(path.join(input, platform, capture.file))
            if (image.length < 24 || image.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a' || image.readUInt32BE(16) !== capture.width || image.readUInt32BE(20) !== capture.height || capture.width < 1 || capture.height < 1 || createHash('sha256').update(image).digest('hex') !== capture.sha256) throw new Error(`Screenshot dimensions or digest mismatch: ${platform}/${capture.file}`)
        }
        for (const id of captureManifest.requiredScreenshots) if (!ids.has(id)) throw new Error(`Missing required screenshot: ${platform}/${id}`)
        manifests.push({ ...captureManifest, artifactPlatform: platform })
    }
    const screenshots = manifests.flatMap(manifest => manifest.screenshots.map(capture => ({ ...capture, id: `${manifest.artifactPlatform}-${capture.id}`, file: `${manifest.artifactPlatform}/${capture.file}`, commit: manifest.commit, platform: manifest.platform })))
    const [header, footer, landing] = await Promise.all(['header.html', 'footer.html', 'index.html'].map(file => fs.readFile(path.join(root, 'docs', file), 'utf8')))
    const description = 'ArchiveBox Desktop: an Electron app for saving and browsing your web archive on Windows, Linux, and Mac. Powered by a local ArchiveBox Docker server.'
    const page = (title, content, gallery = false) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#9b2854"><title>${escape(title)}</title><meta name="description" content="${description}"><link rel="canonical" href="${canonical}${gallery ? 'screenshots/' : ''}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:site_name" content="ArchiveBox"><meta property="og:locale" content="en_US"><meta property="og:url" content="${canonical}${gallery ? 'screenshots/' : ''}"><meta property="og:title" content="${escape(title)}"><meta property="og:description" content="${description}"><meta property="og:image" content="${canonical}assets/social-card.png"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="ArchiveBox — preserve the web"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escape(title)}"><meta name="twitter:description" content="${description}"><meta name="twitter:image" content="${canonical}assets/social-card.png"><link rel="icon" href="${base}assets/favicon.ico"><link rel="apple-touch-icon" href="${base}assets/apple-touch-icon.png"><link rel="stylesheet" href="${base}style.css?v=${revision}"></head><body><a class="skip-link" href="#content">Skip to content</a>${header}<main id="content">${content}</main>${footer}</body></html>`.replaceAll('__BASE__', base)
    const figure = capture => `<figure><a href="${base}screenshots/${escape(capture.file)}?v=${capture.commit}"><img src="${base}screenshots/${escape(capture.file)}?v=${capture.commit}" alt="${escape(capture.title)} — real Electron application" width="${capture.width}" height="${capture.height}" loading="lazy"></a></figure>`
    let gallery = '<h1>Screenshots</h1><p>Real app screens captured by driving the ordinary Electron application. Capture scope and backend details are recorded separately for each platform.</p>'
    if (manifests.length) {
        gallery += '<p>Full captures cover the complete Docker-backed workflow. Startup-only captures cover application setup and the genuine Docker-unavailable state; they do not claim Docker-backed coverage. Each set identifies its actual operating system below.</p>'
        for (const manifest of manifests) {
            const runURL = manifest.workflowRun?.url
            if (runURL && !/^https:\/\/github\.com\/ArchiveBox\/electron-archivebox\/actions\/runs\/\d+$/.test(runURL)) throw new Error('Unexpected workflow run URL')
            gallery += `<p class="provenance">${escape(manifest.platform)} · ${escape(manifest.captureScope)} · ${manifest.packaged ? 'Packaged app' : 'Source checkout'}${manifest.dirty ? ' · Uncommitted changes' : ''} · App ${escape(manifest.appVersion)} · <a href="${repo}/commit/${manifest.commit}">${manifest.commit.slice(0, 12)}</a> · <time datetime="${escape(manifest.generatedAt)}">${escape(manifest.generatedAt)}</time>${runURL ? ` · <a href="${runURL}">Capture run ↗</a>` : ' · Local capture'} · <a href="${manifest.artifactPlatform}/manifest.json">Capture manifest</a></p>`
            if (manifest.dockerImage) gallery += `<p class="provenance">Backend: <code>${escape(manifest.dockerImage.reference)}</code> · Image <code>${escape(manifest.dockerImage.id)}</code></p>`
        }
        gallery += `<ul class="capture-index">${screenshots.map(capture => `<li><a href="#${capture.id}">${escape(capture.platform)} · ${escape(capture.title)}</a></li>`).join('')}</ul>`
        gallery += screenshots.map(capture => `<article class="capture" id="${capture.id}"><h2>${escape(capture.title)} <small>· ${escape(capture.platform)}</small></h2><p>${escape(capture.description || '')}</p>${capture.route ? `<p class="capture-meta"><code>${escape(capture.route)}</code></p>` : ''}${figure(capture)}</article>`).join('')
    } else {
        gallery += `<p class="empty">The first complete automated capture has not been published yet. <a href="${repo}/actions/workflows/ci.yml">View CI progress</a>.</p>`
    }
    await fs.rm(output, { recursive: true, force: true })
    await fs.mkdir(path.join(output, 'screenshots'), { recursive: true })
    for (const file of ['assets', 'style.css']) await fs.cp(path.join(root, 'docs', file), path.join(output, file), { recursive: true })
    for (const manifest of manifests) {
        await fs.mkdir(path.join(output, 'screenshots', manifest.artifactPlatform), { recursive: true })
        await fs.copyFile(path.join(input, manifest.artifactPlatform, 'manifest.json'), path.join(output, 'screenshots', manifest.artifactPlatform, 'manifest.json'))
    }
    for (const capture of screenshots) await fs.copyFile(path.join(input, capture.file), path.join(output, 'screenshots', capture.file))
    const hero = screenshots.find(capture => capture.id === 'linux-archive') || screenshots[0]
    await fs.writeFile(path.join(output, 'index.html'), page('ArchiveBox Desktop · Windows, Linux & Mac', landing.replace('__HERO_SCREENSHOT__', hero ? figure(hero) : '')))
    await fs.writeFile(path.join(output, 'screenshots/index.html'), page('Screenshots · ArchiveBox Desktop', gallery, true))
    await fs.writeFile(path.join(output, '.nojekyll'), '')
    await fs.writeFile(path.join(output, 'CNAME'), new URL(canonical).hostname + '\n')
    await fs.writeFile(path.join(output, 'build.json'), JSON.stringify({ revision, generatedAt: new Date().toISOString(), captures: manifests.map(({ platform, commit }) => ({ platform, commit })), screenshots: screenshots.length }, null, 2) + '\n')
    execFileSync('uv', ['run', '--no-project', 'python', path.join(root, '.github/pages/site.py'), 'render', output, '--baseurl', base], { cwd: root, stdio: 'inherit' });
    const languages = []
    for (const language of ['es', 'fr', 'zh', 'ru', 'ar']) {
        try { if ((await fs.stat(path.join(root, 'docs', language, 'index.html'))).isFile()) languages.push(language) } catch {}
    }
    const alternates = ['en', ...languages].map(language => `<link rel="alternate" hreflang="${language}" href="${canonical}${language === 'en' ? '' : `${language}/`}">`).join('') + `<link rel="alternate" hreflang="x-default" href="${canonical}">`
    if (languages.length) {
        const rootIndex = path.join(output, 'index.html')
        const localizedRoot = (await fs.readFile(rootIndex, 'utf8')).replace('</head>', `${alternates}</head>`).replace('</body>', `<script src="${base}language.js" defer></script></body>`)
        await fs.writeFile(rootIndex, localizedRoot)
        await fs.copyFile(path.join(root, 'docs', 'language.js'), path.join(output, 'language.js'))
    }
    for (const language of languages) {
        const target = path.join(output, language)
        await fs.mkdir(target, { recursive: true })
        const localized = (await fs.readFile(path.join(root, 'docs', language, 'index.html'), 'utf8'))
            .replace('</head>', `${alternates}</head>`)
            .replace('</body>', `<script src="__BASE__language.js" defer></script></body>`)
            .replaceAll('__BASE__', base)
        await fs.writeFile(path.join(target, 'index.html'), localized)
    }
    const sitemapRoutes = ['', ...languages.map(language => `${language}/`), 'screenshots/']
    await fs.writeFile(path.join(output, 'robots.txt'), 'User-agent: *\nAllow: /\n\nSitemap: https://electron.archivebox.io/sitemap.xml\n')
    await fs.writeFile(path.join(output, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemapRoutes.map(route => `<url><loc>${canonical}${route}</loc></url>`).join('')}</urlset>\n`)
    console.log(`Built ${output}: ${screenshots.length} real screenshots`)
}
main().catch(error => { console.error(error); process.exitCode = 1 })

const fs = require('node:fs/promises')
const path = require('node:path')
const assert = require('node:assert/strict')
const { createHash } = require('node:crypto')
const { execFileSync } = require('node:child_process')
const { releaseVersion } = require('./release-version')

async function main() {
    assert.equal(process.env.GITHUB_REF, 'refs/heads/main')
    const version = releaseVersion()
    const tag = `v${version}`
    const repo = process.env.GITHUB_REPOSITORY
    assert.equal(repo, 'ArchiveBox/electron-archivebox')
    const directory = path.resolve('artifacts/releases')
    const assets = ['ArchiveBox-Windows.exe', 'ArchiveBox-Linux.deb', 'ArchiveBox-Linux.rpm', 'ArchiveBox-Mac.dmg']
    const checksums = []
    for (const file of assets) {
        const bytes = await fs.readFile(path.join(directory, file))
        assert.ok(bytes.length > 1000000, `Installer is unexpectedly small: ${file}`)
        checksums.push(`${createHash('sha256').update(bytes).digest('hex')}  ${file}`)
    }
    await fs.writeFile(path.join(directory, 'SHA256SUMS'), `${checksums.join('\n')}\n`)
    const sha = process.env.GITHUB_SHA
    const previous = JSON.parse(execFileSync('gh', ['api', `repos/${repo}/releases?per_page=100`], { encoding: 'utf8' }))
        .filter(release => !release.draft && !release.prerelease && /^v\d+\.\d+\.\d+$/.test(release.tag_name) && release.tag_name !== tag)
        .sort((a, b) => b.created_at.localeCompare(a.created_at))[0]?.tag_name
    const generated = JSON.parse(execFileSync('gh', ['api', `repos/${repo}/releases/generate-notes`, '-f', `tag_name=${tag}`, '-f', `target_commitish=${sha}`, ...(previous ? ['-f', `previous_tag_name=${previous}`] : [])], { encoding: 'utf8' })).body
    const contributorBlock = generated.match(/^## (?:New )?Contributors\n[\s\S]*?(?=^## |\*\*Full Changelog|$(?![\s\S]))/m)?.[0] || ''
    const contributorLines = contributorBlock.split('\n').filter(line => !/@pirate\b|Nick Sweeting/i.test(line))
    const contributors = contributorLines.slice(1).some(line => line.trim()) ? contributorLines.join('\n').trim() : ''
    const from = previous
    const changelog = from ? `[\`${from}...${tag}\`](https://github.com/${repo}/compare/${from}...${tag})` : `[\`${tag}\`](https://github.com/${repo}/commits/${tag})`
    const commits = execFileSync('git', ['log', '--reverse', '--format=%H%x09%s', ...(from ? [`${from}..${sha}`] : [sha])], { encoding: 'utf8' }).trim().split('\n').filter(Boolean)
        .map(line => { const [commit, subject] = line.split('\t'); return `- [${commit.slice(0, 7)}](https://github.com/${repo}/commit/${commit}) ${subject}` }).join('\n')
    let notes = `## Install\n\n- 🪟 **Windows:** Download \`ArchiveBox-Windows.exe\` from the Assets section below and run the installer. Install and start Docker Desktop with Linux containers enabled. If installation fails and **Open Setup Log** is empty, open \`%LOCALAPPDATA%\\SquirrelTemp\\Squirrel-Install.log\` for the install error. See [Windows troubleshooting](https://github.com/${repo}#help--feedback).\n- 🐧 **Debian / Ubuntu:** Download \`ArchiveBox-Linux.deb\` and install it. **Fedora / RHEL:** Download \`ArchiveBox-Linux.rpm\` and install it. Keep Docker Engine running.\n- 🍏 **macOS:** Download \`ArchiveBox-Mac.dmg\`, open it, and drag ArchiveBox to \`/Applications\`. The disk image supports Intel and Apple Silicon Macs. Install and start Docker Desktop before opening ArchiveBox. You may need to \`Right Click > Open\` to launch it the first time.\n\nIf you run into a problem, please [🐛 report it here](https://github.com/${repo}/issues).\n\n[💻 Screenshots](https://electron.archivebox.io/screenshots/) · [📖 Documentation](https://docs.archivebox.io) · [💬 \`@ArchiveBoxApp\`](https://x.com/ArchiveBoxApp)\n\n**Full Changelog:** ${changelog}\n\n## All changes\n\n${commits}\n\nSource: [\`${sha.slice(0, 7)}\`](https://github.com/${repo}/commit/${sha})${contributors ? `\n\n${contributors}` : ''}\n`
    notes = notes.replace(`If you run into a problem, please [🐛 report it here](https://github.com/${repo}/issues).\n\n`, '')
    notes = notes.replace(`[💻 Screenshots](https://electron.archivebox.io/screenshots/) · [📖 Documentation](https://docs.archivebox.io) · [💬 \`@ArchiveBoxApp\`](https://x.com/ArchiveBoxApp)`, `[💻 Screenshots](https://electron.archivebox.io/screenshots/) · [📖 Documentation](https://docs.archivebox.io/) · [💬 \`@ArchiveBoxApp\`](https://x.com/ArchiveBoxApp) · [🐞 Report a bug](https://github.com/${repo}/issues?q=sort%3Aupdated-desc+is%3Aissue+state%3Aopen)`)
    const notesFile = path.join(directory, 'release-notes.md')
    await fs.writeFile(notesFile, notes)
    const gh = args => execFileSync('gh', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim()
    let existing
    // The tag REST endpoint cannot find a draft whose tag is not published yet.
    // gh release view resolves both drafts and published releases.
    try { existing = JSON.parse(gh(['release', 'view', tag, '--repo', repo, '--json', 'apiUrl,body'])) }
    catch (error) {
        if (error.stderr?.toString().trim() !== 'release not found') throw error
    }
    if (existing) {
        assert.ok(existing.body.includes(`Source: ${process.env.GITHUB_SHA}`), 'Existing release belongs to a different source revision')
    } else {
        gh(['release', 'create', tag, '--repo', repo, '--target', sha, '--title', tag, '--notes-file', notesFile, '--draft'])
    }
    gh(['release', 'upload', tag, ...assets.concat('SHA256SUMS').map(file => path.join(directory, file)), '--repo', repo, '--clobber'])
    const release = JSON.parse(gh(['release', 'view', tag, '--repo', repo, '--json', 'apiUrl']))
    // GitHub resolves latest by date and semantic version, even when builds finish out of order.
    gh(['api', '--method', 'PATCH', release.apiUrl, '-F', 'draft=false', '-F', 'prerelease=false', '-f', 'make_latest=legacy'])
    gh(['release', 'edit', tag, '--repo', repo, '--title', tag, '--notes-file', notesFile])
    console.log(`Published https://github.com/${repo}/releases/tag/${tag}`)
}
main().catch(error => { console.error(error); process.exitCode = 1 })

const fs = require('node:fs')
const path = require('node:path')
const assert = require('node:assert/strict')
const { execFileSync } = require('node:child_process')

const root = path.resolve(__dirname, '..')
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim()
const releaseVersion = () => {
    const { version: base, releaseRunBase = 0 } = JSON.parse(git('show', 'HEAD:package.json'))
    if (process.env.GITHUB_REF !== 'refs/heads/main') return base
    if (['workflow_dispatch', 'schedule'].includes(process.env.GITHUB_EVENT_NAME)) {
        const tags = git('tag', '--merged', 'HEAD', '--list', 'v*').split('\n').filter(tag => /^v\d+\.\d+\.\d+$/.test(tag))
        const tag = tags.sort((a, b) => b.slice(1).localeCompare(a.slice(1), undefined, { numeric: true }))[0]
        assert.ok(tag, 'Server compatibility captures require an existing desktop app release')
        const marketingFile = file => file === 'README.md' || file === '.github/workflows/pages.yml' || file.startsWith('docs/') || file.startsWith('.github/pages/')
        assert.ok(git('diff', '--name-only', tag, 'HEAD').split('\n').filter(Boolean).every(marketingFile), 'Unreleased desktop app changes require the normal push release before server compatibility capture')
        return tag.slice(1)
    }
    assert.match(process.env.GITHUB_RUN_NUMBER || '', /^[1-9]\d*$/)
    // Start this version series at its base instead of adding all prior CI runs.
    const increment = Number(process.env.GITHUB_RUN_NUMBER) - releaseRunBase
    assert.ok(Number.isSafeInteger(releaseRunBase) && increment >= 0, 'CI run predates this release series')
    const [major, minor, patch] = base.split('.').map(Number)
    return `${major}.${minor}.${patch + increment}`
}

// Only the exact, reproducible package-version stamp is excluded from source dirtiness.
// All other tracked edits still invalidate CI screenshot provenance.
function sourceProvenance() {
    const changes = git('diff', 'HEAD', '--name-only').split('\n').filter(Boolean)
    if (!changes.length) return { dirty: false, versionStamp: null }
    if (process.env.GITHUB_REF !== 'refs/heads/main' || changes.length !== 2 || changes.some(file => !['package.json', 'package-lock.json'].includes(file))) return { dirty: true, versionStamp: null }
    const version = releaseVersion()
    for (const file of changes) {
        const original = JSON.parse(git('show', `HEAD:${file}`))
        original.version = version
        if (file === 'package-lock.json') original.packages[''].version = version
        try { assert.deepEqual(JSON.parse(fs.readFileSync(path.join(root, file), 'utf8')), original) }
        catch { return { dirty: true, versionStamp: null } }
    }
    return { dirty: false, versionStamp: { version, runNumber: Number(process.env.GITHUB_RUN_NUMBER), files: changes } }
}

if (require.main === module) {
    assert.equal(git('status', '--porcelain', '--untracked-files=no'), '', 'Version stamping requires a clean checkout')
    const version = releaseVersion()
    for (const file of ['package.json', 'package-lock.json']) {
        const filename = path.join(root, file)
        const value = JSON.parse(fs.readFileSync(filename, 'utf8'))
        if (value.version === version) continue
        value.version = version
        if (file === 'package-lock.json') value.packages[''].version = version
        fs.writeFileSync(filename, `${JSON.stringify(value, null, 2)}\n`)
    }
    if (process.env.GITHUB_ENV) fs.appendFileSync(process.env.GITHUB_ENV, `RELEASE_VERSION=${version}\n`)
    console.log(`App version: ${version}`)
}

module.exports = { sourceProvenance, releaseVersion }
